pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address k, bool s) public {
        // _contractOwner is never assigned, so it is address(0); the reference
        // only accepts owner calls from address(0). Prank as that deployer.
        vm.prank(address(0));
        c.setApprovedLogger(k, s);
        assertTrue(c.approvedLoggers(k) == s);
    }
}
